"""New product image runs return generated bytes without model review."""
from pathlib import Path

import pytest

from image_agent.config import AgentConfig
from image_agent.contracts import result_to_bundle
from image_agent.graph_runtime import resume_pipeline
from image_agent.pipeline import run_pipeline
from tests import test_server_tasks as task_fixtures
from tests.test_pipeline import setup
from tests.test_product_long_image_pipeline import long_setup
from tests.test_server_tasks import submit

service = task_fixtures.service


def forbid_reviews(vision):
    async def forbidden(*args, **kwargs):
        raise AssertionError("generated images must never be reviewed")
    for name in ("audit_image", "review_product", "audit_detail_set",
                 "audit_product_long_image_copy"):
        setattr(vision, name, forbidden)


@pytest.mark.parametrize("outputs,count", [(["main_image"], 1),
                                          (["detail_page"], 3),
                                          (["main_image", "detail_page"], 4)])
async def test_default_returns_first_generated_images_without_review(request_data, outputs, count):
    request, deps, vision, gen = setup(request_data | {"output_types": outputs})
    forbid_reviews(vision)
    result = await run_pipeline(request, AgentConfig(), dependencies=deps)
    assert result.status == "succeeded"
    assert len(gen.calls) == count
    assert result.detail_set_audits == []
    for asset in result.assets:
        assert asset.image and asset.status == "succeeded"
        assert asset.quality is None
        assert asset.delivery.mode == "direct" and asset.delivery.score is None
        assert len(asset.candidates) == len(asset.attempts) == 1
        assert asset.candidates[0]["audits"] == []
        assert asset.candidates[0]["selected"] is True
    bundle = result_to_bundle(result)
    assert len(bundle.blobs) == count
    assert all(a.delivery.mode == "direct" for a in bundle.dto.assets)


async def test_default_long_returns_all_sections_without_physical_or_copy_review(request_data):
    request, deps, vision, gen = long_setup(request_data)
    forbid_reviews(vision)
    result = await run_pipeline(request, AgentConfig(), dependencies=deps)
    assert result.status == "succeeded" and len(gen.calls) == 6
    asset = result.assets[0]
    assert asset.delivery.mode == "direct" and asset.quality is None
    bundle = result_to_bundle(result)
    review = bundle.dto.assets[0].long_image_review
    assert len(review.sections) == 6
    assert all(s.status == "succeeded" and s.quality is None and s.copy_audit is None
               and s.delivery.mode == "direct" for s in review.sections)
    assert all(s["candidates"][0]["audits"] == []
               for s in asset.candidates[-1]["metadata"]["segments"])


async def test_direct_delivery_resume_uses_saved_bytes_without_model_calls(request_data, tmp_path):
    request, deps, vision, gen = setup(request_data | {"output_dir": tmp_path})
    forbid_reviews(vision)
    result = await run_pipeline(request, AgentConfig(), dependencies=deps)
    before = len(gen.calls), list(vision.calls)
    resumed = await resume_pipeline(result.run_dir, AgentConfig(), dependencies=deps)
    assert resumed.assets[0].image == result.assets[0].image
    assert resumed.assets[0].delivery.mode == "direct"
    assert (len(gen.calls), vision.calls) == before
    assert Path(resumed.assets[0].file_path).read_bytes() == result.assets[0].image


async def test_bad_generated_bytes_still_fail_without_review(request_data):
    request, deps, vision, gen = setup(request_data)
    forbid_reviews(vision)
    async def corrupt(**kwargs):
        return b"broken image"
    gen.generate = corrupt
    result = await run_pipeline(request, AgentConfig(), dependencies=deps)
    assert result.status == "failed" and result.assets[0].image is None
    assert result.assets[0].delivery is None




async def test_task_service_publishes_direct_delivery_and_original_blob(service, monkeypatch):
    from image_agent import pipeline
    from image_agent.pipeline import Dependencies
    from image_agent.server.worker import Worker
    from tests.fakes import FakeGenerator, FakeVision

    vision, gen = FakeVision(), FakeGenerator()
    forbid_reviews(vision)
    async def load(source):
        return source.data
    deps = Dependencies(vision=vision, generator=gen, load=load)
    async def create(request, config, **kwargs):
        return await run_pipeline(request, config, dependencies=deps, **kwargs)
    monkeypatch.setattr(pipeline, "create_images", create)
    task, _ = await submit(service)
    await Worker(service).run_once()
    state = await service.get_task(task["task_id"])
    assert state["status"] == "completed" and state["core_status"] == "succeeded"
    result = await service.get_result(task["task_id"])
    asset = result["assets"][0]
    assert asset["delivery"]["mode"] == "direct" and asset["quality"] is None
    data, mime = await service.blob(task["task_id"], asset["blob_id"])
    assert data and mime == "image/png" and len(gen.calls) == 1
